create extension if not exists "pgcrypto";
create type public.team_role as enum ('owner','coach','analyst','player','viewer');
create type public.player_position as enum ('setter','outside_hitter','opposite','middle_blocker','libero','defensive_specialist');
create type public.match_status as enum ('scheduled','in_progress','completed','cancelled');
create type public.action_type as enum ('serve','reception','set','attack','block','dig','error');

create table public.users (id uuid primary key references auth.users(id) on delete cascade, display_name text, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.teams (id uuid primary key default gen_random_uuid(), name text not null, abbreviation varchar(8) not null, logo_url text, primary_color varchar(7) not null default '#7056F5', created_by uuid not null references public.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.team_members (team_id uuid not null references public.teams(id) on delete cascade, user_id uuid not null references public.users(id) on delete cascade, role public.team_role not null default 'viewer', created_at timestamptz not null default now(), primary key(team_id,user_id));
create table public.seasons (id uuid primary key default gen_random_uuid(), team_id uuid not null references public.teams(id) on delete cascade, name text not null, starts_on date, ends_on date, is_active boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.players (id uuid primary key default gen_random_uuid(), team_id uuid not null references public.teams(id) on delete cascade, user_id uuid references public.users(id) on delete set null, full_name text not null, jersey_number smallint not null check(jersey_number between 0 and 99), avatar_url text, birth_date date, height_cm smallint check(height_cm between 100 and 250), position public.player_position not null, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(team_id,jersey_number));
create table public.matches (id uuid primary key default gen_random_uuid(), team_id uuid not null references public.teams(id) on delete cascade, season_id uuid references public.seasons(id) on delete set null, match_code text not null unique, played_at timestamptz not null, competition text, venue text, home_team_name text not null, away_team_name text not null, is_home boolean not null default true, best_of smallint not null check(best_of in (3,5)), home_sets smallint not null default 0, away_sets smallint not null default 0, status public.match_status not null default 'scheduled', notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.match_sets (id uuid primary key default gen_random_uuid(), match_id uuid not null references public.matches(id) on delete cascade, set_number smallint not null check(set_number between 1 and 5), home_score smallint not null check(home_score >= 0), away_score smallint not null check(away_score >= 0), unique(match_id,set_number));
create table public.match_players (match_id uuid not null references public.matches(id) on delete cascade, player_id uuid not null references public.players(id) on delete cascade, starter boolean not null default false, sets_played smallint not null default 0 check(sets_played >= 0), primary key(match_id,player_id));
create table public.player_match_stats (id uuid primary key default gen_random_uuid(), match_id uuid not null references public.matches(id) on delete cascade, player_id uuid not null references public.players(id) on delete cascade, serve_attempts int not null default 0 check(serve_attempts>=0), aces int not null default 0 check(aces between 0 and serve_attempts), serve_errors int not null default 0 check(serve_errors between 0 and serve_attempts), attack_attempts int not null default 0 check(attack_attempts>=0), kills int not null default 0 check(kills between 0 and attack_attempts), attack_errors int not null default 0 check(attack_errors between 0 and attack_attempts), solo_blocks int not null default 0, block_assists int not null default 0, digs int not null default 0, dig_errors int not null default 0, reception_attempts int not null default 0, perfect_receptions int not null default 0, good_receptions int not null default 0, poor_receptions int not null default 0, reception_errors int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(match_id,player_id), check(perfect_receptions+good_receptions+poor_receptions+reception_errors<=reception_attempts));
create table public.setter_match_stats (id uuid primary key default gen_random_uuid(), match_id uuid not null references public.matches(id) on delete cascade, player_id uuid not null references public.players(id) on delete cascade, total_touches int not null default 0, perfect_sets int not null default 0, playable_sets int not null default 0, bad_sets int not null default 0, set_errors int not null default 0, assists int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(match_id,player_id), check(total_touches>=perfect_sets+playable_sets+bad_sets+set_errors), check(assists<=perfect_sets+playable_sets+bad_sets+set_errors));
create table public.setter_distribution (id uuid primary key default gen_random_uuid(), setter_stats_id uuid not null references public.setter_match_stats(id) on delete cascade, zone text not null check(zone in ('P2','P3','P4','P6','OTHER')), set_attempts int not null default 0, kills int not null default 0, attack_errors int not null default 0, unique(setter_stats_id,zone), check(kills+attack_errors<=set_attempts));
create table public.videos (id uuid primary key default gen_random_uuid(), match_id uuid not null references public.matches(id) on delete cascade, source_url text not null, storage_path text, duration_seconds numeric, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.match_events (id uuid primary key default gen_random_uuid(), match_id uuid not null references public.matches(id) on delete cascade, video_id uuid references public.videos(id) on delete set null, set_number smallint not null check(set_number between 1 and 5), timestamp_seconds numeric not null check(timestamp_seconds>=0), player_id uuid references public.players(id) on delete set null, action_type public.action_type not null, action_result text not null, target_player_id uuid references public.players(id) on delete set null, zone text, notes text, created_by uuid not null references public.users(id), created_at timestamptz not null default now());
create index idx_members_user on public.team_members(user_id); create index idx_players_team on public.players(team_id); create index idx_matches_team_date on public.matches(team_id,played_at desc); create index idx_stats_player on public.player_match_stats(player_id); create index idx_setter_player on public.setter_match_stats(player_id); create index idx_events_match_time on public.match_events(match_id,set_number,timestamp_seconds);

create or replace function public.can_access_team(requested_team uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from team_members where team_id=requested_team and user_id=auth.uid()) $$;
create or replace function public.can_edit_team(requested_team uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from team_members where team_id=requested_team and user_id=auth.uid() and role in ('owner','coach','analyst')) $$;
alter table public.teams enable row level security; alter table public.team_members enable row level security; alter table public.seasons enable row level security; alter table public.players enable row level security; alter table public.matches enable row level security; alter table public.match_sets enable row level security; alter table public.match_players enable row level security; alter table public.player_match_stats enable row level security; alter table public.setter_match_stats enable row level security; alter table public.setter_distribution enable row level security; alter table public.match_events enable row level security; alter table public.videos enable row level security;
create policy teams_select on public.teams for select using(public.can_access_team(id)); create policy teams_update on public.teams for update using(public.can_edit_team(id));
create policy members_select on public.team_members for select using(public.can_access_team(team_id)); create policy seasons_all on public.seasons for all using(public.can_access_team(team_id)) with check(public.can_edit_team(team_id)); create policy players_all on public.players for all using(public.can_access_team(team_id)) with check(public.can_edit_team(team_id)); create policy matches_all on public.matches for all using(public.can_access_team(team_id)) with check(public.can_edit_team(team_id));
create policy match_sets_all on public.match_sets for all using(exists(select 1 from matches m where m.id=match_id and public.can_access_team(m.team_id))) with check(exists(select 1 from matches m where m.id=match_id and public.can_edit_team(m.team_id)));
create policy match_players_all on public.match_players for all using(exists(select 1 from matches m where m.id=match_id and public.can_access_team(m.team_id))) with check(exists(select 1 from matches m where m.id=match_id and public.can_edit_team(m.team_id)));
create policy player_stats_all on public.player_match_stats for all using(exists(select 1 from matches m where m.id=match_id and public.can_access_team(m.team_id))) with check(exists(select 1 from matches m where m.id=match_id and public.can_edit_team(m.team_id)));
create policy setter_stats_all on public.setter_match_stats for all using(exists(select 1 from matches m where m.id=match_id and public.can_access_team(m.team_id))) with check(exists(select 1 from matches m where m.id=match_id and public.can_edit_team(m.team_id)));
create policy distribution_all on public.setter_distribution for all using(exists(select 1 from setter_match_stats s join matches m on m.id=s.match_id where s.id=setter_stats_id and public.can_access_team(m.team_id))) with check(exists(select 1 from setter_match_stats s join matches m on m.id=s.match_id where s.id=setter_stats_id and public.can_edit_team(m.team_id)));
create policy events_all on public.match_events for all using(exists(select 1 from matches m where m.id=match_id and public.can_access_team(m.team_id))) with check(exists(select 1 from matches m where m.id=match_id and public.can_edit_team(m.team_id)));
create policy videos_all on public.videos for all using(exists(select 1 from matches m where m.id=match_id and public.can_access_team(m.team_id))) with check(exists(select 1 from matches m where m.id=match_id and public.can_edit_team(m.team_id)));
